#!/usr/bin/env python3
"""Generate native/src/release_ids.rs + native/tests/fixtures/mcdata_ids.json from PrismarineJS/minecraft-data.

Usage: node extract_ids.js > ids.json (see tools/protocol_ids/extract_ids.js), then
       python3 gen_protocol_ids.py ids.json <out_rs> <out_fixture_json>
Source of truth: https://github.com/PrismarineJS/minecraft-data (MIT) -- protocol.json per release.
"""
import json, sys
ids = json.load(open(sys.argv[1]))
CB = {'add_entity':'spawn_entity','block_update':'block_change','chunk_batch_finished':'chunk_batch_finished','chunk_batch_start':'chunk_batch_start','container_close':'close_window','container_set_content':'window_items','container_set_data':'craft_progress_bar','container_set_slot':'set_slot','cookie_request':'cookie_request','disconnect':'kick_disconnect','disguised_chat':'profileless_chat','entity_position_sync':'sync_entity_position','forget_level_chunk':'unload_chunk','game_event':'game_state_change','keep_alive':'keep_alive','level_chunk_with_light':'map_chunk','login':'login','move_entity_pos':'rel_entity_move','move_entity_pos_rot':'entity_move_look','open_screen':'open_window','ping':'ping','player_abilities':'abilities','player_chat':'player_chat','player_combat_kill':'death_combat_event','player_info_update':'player_info','player_position':'position','remove_entities':'entity_destroy','remove_mob_effect':'remove_entity_effect','resource_pack_push':'add_resource_pack','respawn':'respawn','section_blocks_update':'multi_block_change','set_action_bar_text':'action_bar','set_cursor_item':'set_cursor_item','set_entity_data':'entity_metadata','set_entity_motion':'entity_velocity','set_equipment':'entity_equipment','set_experience':'experience','set_health':'update_health','set_held_slot':'held_item_slot','set_objective':'scoreboard_objective','set_player_inventory':'set_player_inventory','set_score':'scoreboard_score','set_subtitle_text':'set_title_subtitle','set_title_text':'set_title_text','start_configuration':'start_configuration','system_chat':'system_chat','teleport_entity':'entity_teleport','update_attributes':'entity_update_attributes','update_mob_effect':'entity_effect','block_changed_ack':'acknowledge_player_digging'}
SB = {'accept_teleportation':'teleport_confirm','chat_command':'chat_command','chat':'chat_message','chunk_batch_received':'chunk_batch_received','client_command':'client_command','client_tick_end':'tick_end','configuration_acknowledged':'configuration_acknowledged','container_button_click':'enchant_item','container_click':'window_click','container_close':'close_window','cookie_response':'cookie_response','interact':'use_entity','keep_alive':'keep_alive','move_player_pos':'position','move_player_pos_rot':'position_look','move_player_rot':'look','move_player_status_only':'flying','place_recipe':'craft_recipe_request','player_abilities':'abilities','player_action':'block_dig','player_command':'entity_action','player_loaded':'player_loaded','pong':'pong','rename_item':'name_item','resource_pack':'resource_pack_receive','select_trade':'select_trade','set_carried_item':'held_item_slot','sign_update':'update_sign','swing':'arm_animation','use_item_on':'block_place','use_item':'use_item'}
RUST_MAX = 774          # releases handled here; 775 (26.1) keeps its hand-verified table, >=776 comes from the profile
def table(proto):
    p = ids[str(proto)]['play']; t = {}
    for k, n in CB.items(): t['cb_'+k] = p['toClient'].get(n, -1)
    for k, n in SB.items(): t['sb_'+k] = p['toServer'].get(n, -1)
    # 'player_input' replaced 'steer_vehicle' in 1.21.2; both Rust fields address whichever packet exists.
    pin = p['toServer'].get('player_input', p['toServer'].get('steer_vehicle', -1))
    t['sb_player_input'] = pin; t['sb_steer_vehicle'] = pin
    t['sb_attack'] = -1     # dedicated attack packet only exists from 26.x
    return t
protos = [p for p in sorted(map(int, ids)) if p <= RUST_MAX]
groups = []
for p in protos:
    t = table(p)
    for g in groups:
        if g[1] == t: g[0].append(p); break
    else: groups.append(([p], t))
out = ["//! GENERATED by tools/protocol_ids/gen_protocol_ids.py -- do not edit by hand.",
       "//! Play-state packet IDs for Java Edition protocols 766..=774, extracted from",
       "//! PrismarineJS/minecraft-data (MIT). A value of -1 means the packet does not exist in that release.",
       "use crate::inventory::PacketTable;", "",
       "/// Applies the release-specific play packet IDs. Returns false for protocols outside 766..=774.",
       "pub fn apply(table: &mut PacketTable, proto: i32) -> bool {", "    match proto {"]
for protos_g, t in groups:
    out.append("        " + " | ".join(str(x) for x in protos_g) + " => {")
    for k in sorted(t): out.append(f"            table.{k} = {t[k]};")
    out.append("        }")
out += ["        _ => return false,", "    }", "    true", "}", ""]
open(sys.argv[2], 'w').write("\n".join(out))
fx = {str(p): {'version': ids[str(p)]['version'], 'cb': {'cb_'+k: v for k, v in ((k, table(p)['cb_'+k]) for k in CB)},
               'sb': {'sb_'+k: v for k, v in ((k, table(p)['sb_'+k]) for k in SB)},
               'config': ids[str(p)]['configuration'], 'login': ids[str(p)]['login'],
               'play_raw': ids[str(p)]['play']} for p in map(int, ids)}
json.dump(fx, open(sys.argv[3], 'w'), separators=(',', ':'), sort_keys=True)
print("groups:", [g[0] for g in groups])
